class Solution {
    public int smallestDivisor(int[] loads, int threshold) {
        int lo = 1, hi = 0;
        for (int x : loads) hi = Math.max(hi, x);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long total = 0;
            for (int x : loads) total += (x + mid - 1) / mid;
            if (total <= threshold) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

