int smallestDivisor(int* loads, int loadsSize, int threshold) {
    int lo = 1, hi = 0;
    for (int i = 0; i < loadsSize; i++) if (loads[i] > hi) hi = loads[i];
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        long long total = 0;
        for (int i = 0; i < loadsSize; i++) total += (loads[i] + mid - 1) / mid;
        if (total <= threshold) hi = mid; else lo = mid + 1;
    }
    return lo;
}
